window.AUTH=window.AUTH||{};window.AUTH["21-511"]={"d":"21-511","id":"2021/21-511","n":"Shoop v. Twyford","briefs":[{"k":"petitioner","label":"Brief of petitioner Tim Shoop","date":"2022-02-25","url":"https://www.supremecourt.gov/DocketPDF/21/21-511/214952/20220225080120015_Twyford%20Petitioner%20Brief.PDF","side":"pet","n":61},{"k":"united-states","label":"Brief amicus curiae of United States in support of neither party","date":"2022-03-07","url":"https://www.supremecourt.gov/DocketPDF/21/21-511/217910/20220307185350603_No.%2021-511%20Shoop.pdf","side":"us","n":54},{"k":"respondent","label":"Brief of respondent Raymond Twyford","date":"2022-03-28","url":"https://www.supremecourt.gov/DocketPDF/21/21-511/219593/20220328134645925_21-511%20Brief%20for%20the%20Respondent.pdf","side":"res","n":45},{"k":"reply","label":"Reply of petitioner Tim Shoop","date":"2022-04-05","url":"https://www.supremecourt.gov/DocketPDF/21/21-511/220344/20220405165158873_Twyford%20Reply%20Brief.PDF","side":"pet","n":69}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/596us2r50_2034.pdf","tr":true,"items":[{"t":"case","label":"Allied Chem. Corp. v. Daiflon, Inc.","cite":"449 U.S. 33","y":1980,"id":"1980/79-1895","sc":1,"by":{"0":"16, 40","3":"20"}},{"t":"case","label":"Ballard v. Spradley","cite":"557 F.2d 476","y":1977,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/557/476/","by":{"0":"3"}},{"t":"case","label":"Bank of United States v. Halstead","cite":"23 U.S. 51","y":1825,"id":"scdb/1825-007","sc":1,"by":{"0":"21","3":"15"}},{"t":"case","label":"Barnes v. Black","cite":"544 F.3d 807","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/544/807/","by":{"0":"3","2":"26, 37"},"q":[{"src":"brief","b":2,"text":"[a] prisoner might be a crucial witness in a civil case in federal court that had nothing to do with prisons or criminal law.","cite":"544 F.3d at 810"},{"src":"argument","who":"Ms. Reaves","text":"Going back to the component of your question about whether there are other situations in which there are asymmetrical appeal rights, the Barnes Seventh Circuit decision that Petitioner cited in their opening brief gives several examples of other asymmetrical appeal rights under the collateral order doctrine that includes grants of qualified immunity, particularly partial grants of qualified immunity."}]},{"t":"case","label":"Blevins v. Warden","cite":"2011 WL 6141062","y":2011,"court":"S.D. Ohio Dec. 9","by":{"0":"43"},"q":[{"src":"brief","b":0,"text":"cannot be good cause to collect evidence which cannot be presented.","cite":"2011 WL 6141062"}]},{"t":"case","label":"Bracy v. Gramley","cite":"520 U.S. 899","y":1997,"id":"1996/96-6133","sc":1,"by":{"0":"12, 16, 43","1":"2, 7, 28","2":"46","3":"22"},"q":[{"src":"brief","b":1,"text":"show reason to believe that the petitioner may, if the facts are fully developed, be able to demonstrate that he is . . . entitled to relief.","cite":"520 U.S. 899, 908-909"}]},{"t":"case","label":"Carbo v. United States","cite":"364 U.S. 611","y":1961,"id":"1960/72","sc":1,"by":{"0":"30","1":"19","2":"37"},"q":[{"src":"brief","b":1,"text":"prosecute[d] * * * in the proper jurisdiction wherein the offense was committed.","cite":"364 U.S. 611, 615"},{"src":"argument","who":"Mr. Flowers","text":"Years later, in Carbo, this Court clarified that that was not the case and that 2241(a) has no bearing on writs issued under (c)(5). So Hayman comes out the same way, and Price came out differently under an old statute that it failed to consider."}]},{"t":"case","label":"Carlisle v. United States","cite":"517 U.S. 416","y":1996,"id":"1995/94-9247","sc":1,"by":{"0":"passim","1":"11","3":"2, 17"},"q":[{"src":"brief","b":0,"text":"agreeable to the usages and principles of law.","cite":"517 U.S. at 429"},{"src":"brief","b":0,"text":"necessary or appropriate in aid of","cite":"517 U.S. at 429"},{"src":"brief","b":3,"text":"agreeable to the usages and principles of law.","cite":"517 U.S. at 428"}]},{"t":"case","label":"Cheney v. United States Dist. Court","cite":"542 U.S. 367","y":2004,"id":"2003/03-475","sc":1,"by":{"0":"40","3":"7"}},{"t":"case","label":"Clinton v. Goldsmith","cite":"526 U.S. 529","y":1999,"id":"1998/98-347","sc":1,"by":{"0":"23, 34, 39, 46","1":"10, 11, 17","3":"2"},"q":[{"src":"brief","b":0,"text":"unjustifiable either as ‘necessary’ or as ‘appropriate.’","cite":"526 U.S. at 534"},{"src":"brief","b":1,"text":"the Act does not enlarge that jurisdiction,","cite":"526 U.S. 529, 535"},{"src":"brief","b":1,"text":"a power essentially equitable and, as such, not generally available to provide alternatives to other, adequate remedies at law.","cite":"526 U.S. at 537"}]},{"t":"case","label":"Cornwell v. Bradshaw","cite":"559 F.3d 398","y":2009,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/559/398/","by":{"0":"48"}},{"t":"case","label":"Cullen v. Pinholster","cite":"563 U.S. 170","y":2011,"id":"2010/09-1088","sc":1,"by":{"0":"passim","1":"5, 26, 27","2":"4, 43","3":"21"},"q":[{"src":"brief","b":0,"text":"to the record that was before the state court.","cite":"563 U.S. 170, 181–82"},{"src":"brief","b":0,"text":"the record that was before the state court.","cite":"563 U.S. at 181"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"the evidence presented in the State court proceeding.","cite":"563 U. S. 170"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"AEDPA's statutory scheme is designed to strongly discourage them from doing so.","cite":"563 U. S., at 186"},{"src":"argument","who":"Justice Sotomayor","text":"No, that's different than whether it would be admissible, because that's what Justice Thomas was asking about, Cullen versus Pinholster, that there is an obligation on habeas to ensure that it's useful for some purpose."}]},{"t":"case","label":"DA’s Office v. Osborne","cite":"557 U.S. 52","y":2009,"id":"2008/08-6","sc":1,"by":{"0":"48"}},{"t":"case","label":"Davila v. Davis","cite":"137 S. Ct. 2058","y":2017,"id":"2016/16-6219","sc":1,"by":{"0":"45, 46"},"q":[{"src":"brief","b":0,"text":"aggravate the harm to federalism that federal habeas review necessarily causes.","cite":"137 S. Ct. at 2070"}]},{"t":"case","label":"De Beers Consol. Mines, Ltd. v. United States","cite":"325 U.S. 212","y":1945,"id":"scdb/1944-154","sc":1,"by":{"0":"13, 24"},"q":[{"src":"brief","b":0,"text":"agreeable to the usages and principles of law.","cite":"325 U.S. 212, 221–23"}]},{"t":"case","label":"Dep’t of Homeland Sec. v. Thuraissigiam","cite":"140 S. Ct. 1959","y":2020,"id":"2019/19-161","sc":1,"by":{"0":"28","1":"18"},"q":[{"src":"brief","b":0,"text":"the writ of habeas corpus ‘has traditionally been a means to secure release from unlawful detention.’","cite":"140 S. Ct. at 1963"}]},{"t":"case","label":"Dig. Equip. Corp. v. Desktop Direct, Inc.","cite":"511 U.S. 863","y":1994,"id":"1993/93-405","sc":1,"by":{"0":"2, 3","2":"19, 21, 22, 24"},"q":[{"src":"brief","b":0,"text":"would render such important questions effectively unreviewable on appeal from final judgment in the underlying action.","cite":"511 U.S. 863, 867"},{"src":"brief","b":2,"text":"end[ing] the litigation on the merits and leav[ing] nothing more for the court to do but execute the judgment.","cite":"511 U.S. 863, 867"},{"src":"brief","b":2,"text":"stressed that [this exception] must ‘never be allowed to swallow the general rule that a party is entitled to a single appeal, to be deferred until final judgment has been entered.’","cite":"511 U.S. at 868"},{"src":"opinion","who":"Justice Breyer, dissenting","text":"`narrow' exception [that] should stay that way and never be allowed to swallow the general rule that a party is entitled to a single appeal, to be deferred until fnal judgment has been entered.","cite":"511 U. S. 863, 868"},{"src":"opinion","who":"Justice Breyer, dissenting","text":"[1] that are conclusive, [2] that resolve important questions completely separate from the merits, and [3] that would render such important questions effectively unreviewable on appeal from fnal judgment in the underlying action.","cite":"511 U. S., at 867"}]},{"t":"case","label":"Edwards v. Vannoy","cite":"141 S. Ct. 1547","y":2021,"id":"2020/19-5807","sc":1,"by":{"0":"passim","3":"9"},"q":[{"src":"brief","b":0,"text":"produce (habeas) a prisoner’s person (corpus).","cite":"141 S. Ct. 1547, 1566"},{"src":"brief","b":0,"text":"functioned more like a subpoena to procure a prisoner’s presence to testify in court.","cite":"141 S. Ct. at 1566"}]},{"t":"case","label":"Hardwick v. Doolittle","cite":"558 F.2d 292","y":1977,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/558/292/","by":{"0":"25"}},{"t":"case","label":"Harrington v. Richter","cite":"562 U.S. 86","y":2011,"id":"2010/09-587","sc":1,"by":{"0":"46"},"q":[{"src":"brief","b":0,"text":"Federal habeas review of state convictions … intrudes on state sovereignty to a degree matched by few exercises of federal judicial authority.","cite":"562 U.S. 86, 103"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"State's signifcant interest in repose for concluded litigation.","cite":"562 U. S., at 103"}]},{"t":"case","label":"Harris v. Nelson","cite":"394 U.S. 286","y":1969,"id":"1968/199","sc":1,"by":{"0":"17, 42, 43, 48","1":"12, 15, 27, 28","2":"passim","3":"15, 18, 22"},"q":[{"src":"brief","b":0,"text":"reason to believe that [he] may, if the facts are fully developed, be able to demonstrate that he is confined illegally and is therefore entitled to relief.","cite":"394 U.S. at 300"},{"src":"brief","b":1,"text":"courts may rely upon [the All Writs Act] in issuing orders appropriate to assist them in conducting factual inquiries.","cite":"394 U.S. at 299"},{"src":"brief","b":1,"text":"by analogy to existing rules or otherwise in conformity with judicial usage.","cite":"394 U.S. at 299"},{"src":"brief","b":2,"text":"legislatively approved source of procedural instruments designed to achieve the rational ends of law.","cite":"394 U.S. 286, 299"},{"src":"brief","b":3,"text":"may, if the facts are fully developed, be able to demonstrate that he is confined illegally and is therefore entitled to relief.","cite":"394 U.S. at 300"}]},{"t":"case","label":"Hohn v. United States","cite":"524 U.S. 236","y":1998,"id":"1997/96-8986","sc":1,"by":{"0":"46"}},{"t":"case","label":"Home Depot U.S.A., Inc. v. Jackson","cite":"139 S. Ct. 1743","y":2019,"id":"2018/17-1471","sc":1,"by":{"0":"25"}},{"t":"case","label":"I.N.S. v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"by":{"0":"30"}},{"t":"case","label":"Ivey v. Harney","cite":"47 F.3d 181","y":1995,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/47/181/","by":{"0":"passim","1":"14","2":"33","3":"passim"},"q":[{"src":"brief","b":0,"text":"supersede the common law powers of the federal courts.","cite":"47 F.3d at 184"},{"src":"brief","b":0,"text":"permitted the district court to issue orders to transport an inmate only to court or to testify, not to an outside medical facility for a medical exam.","cite":"47 F.3d at 185"},{"src":"brief","b":1,"text":"require[] equipment that only [is] available at an outside facility.","cite":"47 F.3d at 187"},{"src":"argument","who":"Mr. Flowers","text":"And it was not consistent with that because, as Judge Easterbrook explained in his opinion for the Court in Ivey in the Seventh Circuit, 2241(c) prohibits writs of habeas corpus except in very -- I'm sorry."}]},{"t":"case","label":"Jackson v. Vasquez","cite":"1 F.3d 885","y":1993,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/1/885/","by":{"0":"3, 34","2":"26"}},{"t":"case","label":"Jones v. Lilly","cite":"37 F.3d 964","y":1994,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/37/964/","by":{"0":"passim","3":"3, 7, 15"},"q":[{"src":"brief","b":0,"text":"actually aid the court in the performance of its duties.","cite":"37 F.3d 964, 968"},{"src":"brief","b":0,"text":"in no way implies that courts have the power to fashion any writ they deem desirable.","cite":"37 F.3d at 968"},{"src":"brief","b":3,"text":"fashion any writ they deem desirable.","cite":"37 F.3d at 968"}]},{"t":"case","label":"Jurado v. Davis","cite":"12 F.4th 1084","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/12/1084/","by":{"0":"43"}},{"t":"case","label":"Lafferty v. Benzon","cite":"933 F.3d 1237","y":2019,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/933/1237/","by":{"0":"43"}},{"t":"case","label":"Leavitt v. Arave","cite":"682 F.3d 1138","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/682/1138/","by":{"0":"48"}},{"t":"case","label":"Lowery v. McCaughtry","cite":"954 F.2d 422","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/954/422/","by":{"0":"25","3":"8, 14, 15"},"q":[{"src":"brief","b":3,"text":"traditional writs that have not been altered or abolished by some other statute.","cite":"954 F.2d at 423"}]},{"t":"case","label":"NFIB v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"by":{"0":"22, 34"},"q":[{"src":"brief","b":0,"text":"in service to, a granted power.","cite":"567 U.S. 519, 560"},{"src":"brief","b":0,"text":"best evidence of Congress’s intent is the statutory text,","cite":"567 U.S. at 544"}]},{"t":"case","label":"Pa. Bureau of Corr. v. U.S. Marshals Serv.","cite":"474 U.S. 34","y":1985,"id":"1985/84-489","sc":1,"by":{"0":"passim","1":"10, 11, 14, 19, 22","2":"passim","3":"passim"},"q":[{"src":"brief","b":0,"text":"specifically ad- dresses the particular issue at hand.","cite":"474 U.S. 34, 43"},{"src":"brief","b":0,"text":"fill[] the interstices of federal judicial power when those gaps threaten[] to thwart the otherwise proper exercise of federal courts’ jurisdiction,","cite":"474 U.S. at 41"},{"src":"brief","b":1,"text":"the interstices of federal judicial power when those gaps threaten[] to thwart the otherwise proper exercise of federal courts’ jurisdiction.","cite":"474 U.S. at 41"},{"src":"brief","b":1,"text":"Where a statute specifically addresses the particular issue at hand, it is that authority, and not the All Writs Act, that is controlling.","cite":"474 U.S. at 43"},{"src":"brief","b":3,"text":"procedures appears inconvenient or less appropriate.","cite":"474 U.S. at 43"},{"src":"argument","who":"Mr. Flowers","text":"That makes it like the Carlisle case, it makes it like the Syngenta case, and it makes it like the Pennsylvania Bureau of Corrections case in which this Court said that when -- when there's a statute that governs a particular issue, parties may not evade that using the All Writs Act."},{"src":"argument","who":"Mr. Flowers","text":"So, in Syngenta, in Carlisle, and to some extent Pennsylvania Bureau of Corrections, the Court has made absolutely crystal-clear that when there's a statute or a rule that governs a situation, you cannot use the All Writs Act to evade that."}]},{"t":"case","label":"Price v. Johnston","cite":"334 U.S. 266","y":1948,"id":"scdb/1947-084","sc":1,"by":{"0":"24","1":"12, 16, 17, 20, 23","2":"passim","3":"passim"},"q":[{"src":"brief","b":0,"text":"in vogue at the common law or in the English judicial system.","cite":"334 U.S. 266, 282"},{"src":"brief","b":1,"text":"says that the writ must be agreeable to the usages and principles of ‘law,’ a term which is unlimited by the common law or the English law.","cite":"334 U.S. at 282"},{"src":"brief","b":1,"text":"[t]he historic * * * usage of the writ * * * is to produce the body of a person before a court for whatever purpose might be essential to the proper disposition of a cause.","cite":"334 U.S. at 283"},{"src":"brief","b":2,"text":"reasonably necessary in the interests of justice.","cite":"334 U.S. 266, 279, 286"},{"src":"brief","b":2,"text":"an ossification of the practice and procedure of more than a century and a half ago.","cite":"334 U.S. 266, 282"},{"src":"brief","b":3,"text":"necessarily confined to the precise forms of … writ[s] in vogue at the common law or in the English judicial system.","cite":"334 U.S. at 282"},{"src":"brief","b":3,"text":"‘necessary’ in the sense that the court could not otherwise physically discharge its … duties.","cite":"334 U.S. at 279"}]},{"t":"case","label":"Pulliam v. Allen","cite":"466 U.S. 522","y":1984,"id":"1983/82-1432","sc":1,"by":{"0":"20"}},{"t":"case","label":"Rawlins v. Kansas","cite":"714 F.3d 1189","y":2013,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/714/1189/","by":{"0":"25"}},{"t":"case","label":"Roche v. Evaporated Milk Ass’n","cite":"319 U.S. 21","y":1943,"id":"scdb/1942-071","sc":1,"by":{"0":"22, 40"},"q":[{"src":"brief","b":0,"text":"confine an inferior court to a lawful exercise of its prescribed jurisdiction.","cite":"319 U.S. 21, 26"}]},{"t":"case","label":"Ryan v. Gonzales","cite":"568 U.S. 57","y":2013,"id":"2012/10-930","sc":1,"by":{"0":"49","1":"13"}},{"t":"case","label":"Sibbald v. United States","cite":"37 U.S. 488","y":1838,"id":"scdb/1838-037","sc":1,"by":{"0":"21"}},{"t":"case","label":"Syngenta Crop Prot., Inc. v. Henson","cite":"537 U.S. 28","y":2002,"id":"2002/01-757","sc":1,"by":{"0":"23","1":"11","3":"16"},"q":[{"src":"brief","b":1,"text":"avoid complying with the statutory requirements for removal,","cite":"537 U.S. at 32"},{"src":"argument","who":"Mr. Flowers","text":"That makes it like the Carlisle case, it makes it like the Syngenta case, and it makes it like the Pennsylvania Bureau of Corrections case in which this Court said that when -- when there's a statute that governs a particular issue, parties may not evade that using the All Writs Act."},{"src":"argument","who":"Mr. Flowers","text":"So, in Syngenta, in Carlisle, and to some extent Pennsylvania Bureau of Corrections, the Court has made absolutely crystal-clear that when there's a statute or a rule that governs a situation, you cannot use the All Writs Act to evade that."}]},{"t":"case","label":"Thomas v. Taylor","cite":"170 F.3d 466","y":1999,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/170/466/","by":{"0":"48"}},{"t":"case","label":"Twyford v. Shoop","cite":"11 F.4th 518","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/11/518/","by":{"0":"2"}},{"t":"case","label":"Twyford v. Warden","cite":"2020 WL 1308318","y":2020,"court":"S.D. Ohio Mar. 19","by":{"0":"2"}},{"t":"case","label":"U.S. Alkali Export Ass’n v. United States","cite":"325 U.S. 196","y":1945,"id":"scdb/1944-087","sc":1,"by":{"0":"21","1":"11"},"q":[{"src":"brief","b":1,"text":"as a substitute for an authorized appeal,","cite":"325 U.S. 196, 203"}]},{"t":"case","label":"United States v. Blake","cite":"868 F.3d 960","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/868/960/","by":{"0":"21"}},{"t":"case","label":"United States v. Denedo","cite":"556 U.S. 904","y":2009,"id":"2008/08-267","sc":1,"by":{"0":"22, 23","1":"10"}},{"t":"case","label":"United States v. Hayman","cite":"342 U.S. 205","y":1952,"id":"scdb/1951-024","sc":1,"by":{"0":"passim","1":"12, 16, 23","2":"30, 31, 35, 39","3":"13, 14"},"q":[{"src":"brief","b":0,"text":"look[s] first to the common law.","cite":"342 U.S. 205, 221 n.35"},{"src":"brief","b":0,"text":"[i]n determining what auxiliary writs are ‘agreeable to the usages and principles of law.’","cite":"342 U.S. at 221 n.35"},{"src":"argument","who":"Mr. Flowers","text":"The next case I think is Hayman. Hayman comes out exactly the same way under our theory, though the reasoning would be slightly different in light of subsequent legal developments."}]},{"t":"case","label":"United States v. Morgan","cite":"346 U.S. 502","y":1954,"id":"scdb/1953-020","sc":1,"by":{"0":"21, 22"}},{"t":"case","label":"United States v. New York Tel. Co.","cite":"434 U.S. 159","y":1977,"id":"1977/76-835","sc":1,"by":{"0":"22, 23, 27, 34","1":"11, 12, 16","2":"passim","3":"15, 16, 19"},"q":[{"src":"brief","b":0,"text":"to achieve ‘the rational ends of law.’","cite":"434 U.S. 159, 172"},{"src":"brief","b":0,"text":"consistent with the intent of Congress","cite":"434 U.S. at 172"},{"src":"brief","b":1,"text":"not limited to those situations where it is ‘necessary’ to issue the writ or order ‘in the sense that the court could not otherwise discharge its * * * duties.’","cite":"434 U.S. at 173"},{"src":"brief","b":1,"text":"telephone companies to assist in the installation and operation of pen registers","cite":"434 U.S. at 177"},{"src":"brief","b":2,"text":"a legislatively approved source of procedural instruments designed to achieve the rational ends of law.","cite":"434 U.S. 159, 172"},{"src":"brief","b":2,"text":"flexibly in conformity with these principles,","cite":"434 U.S. 159, 173"},{"src":"argument","who":"Mr. Flowers","text":"And I do want to stress that allowing it under the All Writs Act would be inconsistent with the cases this Court's announced in the years since New York Telephone that have attempted to rein in, shall we say, overly expansive readings of the Act."}]},{"t":"case","label":"Vega v. Semple","cite":"963 F.3d 259","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/963/259/","by":{"0":"38"}},{"t":"case","label":"Wainwright v. Sykes","cite":"433 U.S. 72","y":1977,"id":"1976/75-1578","sc":1,"by":{"0":"50"},"q":[{"src":"brief","b":0,"text":"‘main event,’ so to speak, rather than a ‘tryout on the road’ for what will later be the determinative federal habeas hearing.","cite":"433 U.S. 72, 90"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"main event, so to speak, rather than a tryout on the road for what will later be the determinative federal habeas hearing.","cite":"433 U. S. 72, 90"}]},{"t":"case","label":"Washington v. United States","cite":"460 U.S. 536","y":1983,"id":"1982/81-969","sc":1,"by":{"0":"19"},"q":[{"src":"brief","b":0,"text":"statutory provisions are most easily understood in light of their history.","cite":"460 U.S. 536, 538"}]},{"t":"usc","label":"18 U.S.C. § 3599","url":"https://www.law.cornell.edu/uscode/text/18/3599","stext":{"head":"§3599. Counsel for financially unable defendants","paras":[[0,"(a)(1) Notwithstanding any other provision of law to the contrary, in every criminal action in which a defendant is charged with a crime which may be punishable by death, a defendant who is or becomes financially unable to obtain adequate representation or investigative, expert, or other reasonably necessary services at any time either—"],[1,"(A) before judgment; or"],[1,"(B) after the entry of a judgment imposing a sentence of death but before the execution of that judgment;"],[0,"shall be entitled to the appointment of one or more attorneys and the furnishing of such other services in accordance with subsections (b) through (f)."],[0,"(2) In any post conviction proceeding under section 2254 or 2255 of title 28, United States Code, seeking to vacate or set aside a death sentence, any defendant who is or becomes financially unable to obtain adequate representation or investigative, expert, or other reasonably necessary services shall be entitled to the appointment of one or more attorneys and the furnishing of such other services in accordance with subsections (b) through (f)."],[0,"(b) If the appointment is made before judgment, at least one attorney so appointed must have been admitted to practice in the court in which the prosecution is to be tried for not less than five years, and must have had not less than three years experience in the actual trial of felony prosecutions in that court."],[0,"(c) If the appointment is made after judgment, at least one attorney so appointed must have been admitted to practice in the court of appeals for not less than five years, and must have had not less than three years experience in the handling of appeals in that court in felony cases."],[0,"(d) With respect to subsections (b) and (c), the court, for good cause, may appoint another attorney whose background, knowledge, or experience would otherwise enable him or her to properly represent the defendant, with due consideration to the seriousness of the possible penalty and to the unique and complex nature of the litigation."],[0,"(e) Unless replaced by similarly qualified counsel upon the attorney's own motion or upon motion of the defendant, each attorney so appointed shall represent the defendant throughout every subsequent stage of available judicial proceedings, including pretrial proceedings, trial, sentencing, motions for new trial, appeals, applications for writ of certiorari to the Supreme Court of the United States, and all available post-conviction process, together with applications for stays of execution and other appropriate motions and procedures, and shall also represent the defendant in such competency proceedings and proceedings for executive or other clemency as may be available to the defendant."],[0,"(f) Upon a finding that investigative, expert, or other services are reasonably necessary for the representation of the defendant, whether in connection with issues relating to guilt or the sentence, the court may authorize the defendant's attorneys to obtain such services on behalf of the defendant and, if so authorized, shall order the payment of fees and expenses therefor under subsection (g). No ex parte proceeding, communication, or request may be considered pursuant to this section unless a proper showing is made concerning the need for confidentiality. Any such proceeding, communication, or request shall be transcribed and made a part of the record available for appellate review."],[0,"(g)(1) Compensation shall be paid to attorneys appointed under this subsection 1 at a rate of not more than $125 per hour for in-court and out-of-court time. The Judicial Conference is authorized to raise the maximum for hourly payment specified in the 2 paragraph up to the aggregate of the overall average percentages of the adjustments in the rates of pay for the General Schedule made pursuant to section 5305 3 of title 5 on or after such date. After the rates are raised under the preceding sentence, such hourly range may be raised at intervals of not less than one year, up to the aggregate of the overall average percentages of such adjustments made since the last raise under this paragraph."],[0,"(2) Fees and expenses paid for investigative, expert, and other reasonably necessary services authorized under subsection (f) shall not exceed $7,500 in any case, unless payment in excess of that limit is certified by the court, or by the United States magistrate judge, if the services were rendered in connection with the case disposed of entirely before such magistrate judge, as necessary to provide fair compensation for services of an unusual character or duration, and the amount of the excess payment is approved by the chief judge of the circuit. The chief judge of the circuit may delegate such approval authority to an active or senior circuit judge."],[0,"(3) The amounts paid under this paragraph 4 for services in any case shall be disclosed to the public, after the disposition of the petition."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3599?type=usc&year=mostrecent&link-type=html"},"by":{"0":"11, 37, 38","2":"10, 11, 44","3":"21"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"3"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","stext":{"head":"§1291. Final decisions of district courts","paras":[[0,"The courts of appeals (other than the United States Court of Appeals for the Federal Circuit) shall have jurisdiction of appeals from all final decisions of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, except where a direct review may be had in the Supreme Court. The jurisdiction of the United States Court of Appeals for the Federal Circuit shall be limited to the jurisdiction described in sections 1292(c) and (d) and 1295 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1291?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2","2":"1, 18, 19","3":"1, 5, 6"},"q":[{"src":"brief","b":2,"text":"final decisions of the district courts.","cite":"28 U.S.C. § 1291"},{"src":"opinion","who":"Justice Breyer, dissenting","text":"fnal decisions of the district courts.","cite":"28 U. S. C. § 1291"}]},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","by":{"0":"2"}},{"t":"usc","label":"28 U.S.C. § 1651","url":"https://www.law.cornell.edu/uscode/text/28/1651","subs":["(a)"],"stext":{"head":"§1651. Writs","paras":[[0,"(a) The Supreme Court and all courts established by Act of Congress may issue all writs necessary or appropriate in aid of their respective jurisdictions and agreeable to the usages and principles of law."],[0,"(b) An alternative writ or rule nisi may be issued by a justice or judge of a court which has jurisdiction."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1651?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim","1":"passim","2":"2, 27, 28","3":"7, 20"},"q":[{"src":"brief","b":0,"text":"issue all writs necessary or appropriate in aid of their respective jurisdictions and agreeable to the usages and principles of law.","cite":"28 U.S.C. §1651(a)"},{"src":"brief","b":0,"text":"all writs necessary or appropriate in aid of their respective jurisdictions and agreeable to the usages and principles of law.","cite":"28 U.S.C. §1651(a)"},{"src":"brief","b":1,"text":"issue all writs necessary or appropriate in aid of their respective jurisdictions and agreeable to the usages and principles of law,","cite":"28 U.S.C. 1651(a)"},{"src":"brief","b":1,"text":"necessary or appropriate in aid of their respective jurisdictions and agreeable to the usages and principles of law.","cite":"28 U.S.C. 1651(a)"},{"src":"brief","b":2,"text":"The Supreme Court and all courts established by Act of Congress may issue all writs necessary or appropriate in aid of their respective jurisdictions and agreeable to the usages and principles of law.","cite":"28 U.S.C. § 1651(a)"},{"src":"brief","b":2,"text":"agreeable to the usages and principles of law,","cite":"28 U.S.C. § 1651(a)"}]},{"t":"usc","label":"28 U.S.C. § 2241","url":"https://www.law.cornell.edu/uscode/text/28/2241","subs":["(c)(1964)","(c)","(c)(5)","(c)(3)"],"stext":{"head":"§2241. Power to grant writ","paras":[[0,"(a) Writs of habeas corpus may be granted by the Supreme Court, any justice thereof, the district courts and any circuit judge within their respective jurisdictions. The order of a circuit judge shall be entered in the records of the district court of the district wherein the restraint complained of is had."],[0,"(b) The Supreme Court, any justice thereof, and any circuit judge may decline to entertain an application for a writ of habeas corpus and may transfer the application for hearing and determination to the district court having jurisdiction to entertain it."],[0,"(c) The writ of habeas corpus shall not extend to a prisoner unless—"],[1,"(1) He is in custody under or by color of the authority of the United States or is committed for trial before some court thereof; or"],[1,"(2) He is in custody for an act done or omitted in pursuance of an Act of Congress, or an order, process, judgment or decree of a court or judge of the United States; or"],[1,"(3) He is in custody in violation of the Constitution or laws or treaties of the United States; or"],[1,"(4) He, being a citizen of a foreign state and domiciled therein is in custody for an act done or omitted under any alleged right, title, authority, privilege, protection, or exemption claimed under the commission, order or sanction of any foreign state, or under color thereof, the validity and effect of which depend upon the law of nations; or"],[1,"(5) It is necessary to bring him into court to testify or for trial."],[0,"(d) Where an application for a writ of habeas corpus is made by a person in custody under the judgment and sentence of a State court of a State which contains two or more Federal judicial districts, the application may be filed in the district court for the district wherein such person is in custody or in the district court for the district within which the State court was held which convicted and sentenced him and each of such district courts shall have concurrent jurisdiction to entertain the application. The district court for the district wherein such an application is filed in the exercise of its discretion and in furtherance of justice may transfer the application to the other district court for hearing and determination."],[0,"(e)(1) No court, justice, or judge shall have jurisdiction to hear or consider an application for a writ of habeas corpus filed by or on behalf of an alien detained by the United States who has been determined by the United States to have been properly detained as an enemy combatant or is awaiting such determination."],[0,"(2) Except as provided in paragraphs (2) and (3) of section 1005(e) of the Detainee Treatment Act of 2005 (10 U.S.C. 801 note), no court, justice, or judge shall have jurisdiction to hear or consider any other action against the United States or its agents relating to any aspect of the detention, transfer, treatment, trial, or conditions of confinement of an alien who is or was detained by the United States and has been determined by the United States to have been properly detained as an enemy combatant or is awaiting such determination."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2241?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim","1":"23, passim, 5, 7, 8, 21, 23","2":"36, 37, 15, 31, 36, 37, 3, 37, 38","3":"passim"},"q":[{"src":"brief","b":1,"text":"[i]t is necessary to bring him into court to testify or for trial.","cite":"28 U.S.C. 2241(c)(5)"},{"src":"brief","b":1,"text":"[i]t is necessary to bring [a prisoner] into court to testify or for trial,","cite":"28 U.S.C. 2241(c)(5)"}]},{"t":"usc","label":"28 U.S.C. § 2254","url":"https://www.law.cornell.edu/uscode/text/28/2254","subs":["(d)","(d)(1)","(d)(2)","(e)(2)"],"stext":{"head":"§2254. State custody; remedies in Federal courts","paras":[[0,"(a) The Supreme Court, a Justice thereof, a circuit judge, or a district court shall entertain an application for a writ of habeas corpus in behalf of a person in custody pursuant to the judgment of a State court only on the ground that he is in custody in violation of the Constitution or laws or treaties of the United States."],[0,"(b)(1) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted unless it appears that—"],[1,"(A) the applicant has exhausted the remedies available in the courts of the State; or"],[1,"(B)(i) there is an absence of available State corrective process; or"],[1,"(ii) circumstances exist that render such process ineffective to protect the rights of the applicant."],[0,"(2) An application for a writ of habeas corpus may be denied on the merits, notwithstanding the failure of the applicant to exhaust the remedies available in the courts of the State."],[0,"(3) A State shall not be deemed to have waived the exhaustion requirement or be estopped from reliance upon the requirement unless the State, through counsel, expressly waives the requirement."],[0,"(c) An applicant shall not be deemed to have exhausted the remedies available in the courts of the State, within the meaning of this section, if he has the right under the law of the State to raise, by any available procedure, the question presented."],[0,"(d) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted with respect to any claim that was adjudicated on the merits in State court proceedings unless the adjudication of the claim—"],[1,"(1) resulted in a decision that was contrary to, or involved an unreasonable application of, clearly established Federal law, as determined by the Supreme Court of the United States; or"],[1,"(2) resulted in a decision that was based on an unreasonable determination of the facts in light of the evidence presented in the State court proceeding."],[0,"(e)(1) In a proceeding instituted by an application for a writ of habeas corpus by a person in custody pursuant to the judgment of a State court, a determination of a factual issue made by a State court shall be presumed to be correct. The applicant shall have the burden of rebutting the presumption of correctness by clear and convincing evidence."],[0,"(2) If the applicant has failed to develop the factual basis of a claim in State court proceedings, the court shall not hold an evidentiary hearing on the claim unless the applicant shows that—"],[1,"(A) the claim relies on—"],[2,"(i) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable; or"],[2,"(ii) a factual predicate that could not have been previously discovered through the exercise of due diligence; and"],[1,"(B) the facts underlying the claim would be sufficient to establish by clear and convincing evidence that but for constitutional error, no reasonable factfinder would have found the applicant guilty of the underlying offense."],[0,"(f) If the applicant challenges the sufficiency of the evidence adduced in such State court proceeding to support the State court's determination of a factual issue made therein, the applicant, if able, shall produce that part of the record pertinent to a determination of the sufficiency of the evidence to support such determination. If the applicant, because of indigency or other reason is unable to produce such part of the record, then the State shall produce such part of the record and the Federal court shall direct the State to do so by order directed to an appropriate State official. If the State cannot provide such pertinent part of the record, then the court shall determine under the existing facts and circumstances what weight shall be given to the State court's factual determination."],[0,"(g) A copy of the official records of the State court, duly certified by the clerk of such court to be a true and correct copy of a finding, judicial opinion, or other reliable written indicia showing such a factual determination by the State court shall be admissible in the Federal court proceeding."],[0,"(h) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel for an applicant who is or becomes financially unable to afford counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(i) The ineffectiveness or incompetence of counsel during Federal or State collateral post-conviction proceedings shall not be a ground for relief in a proceeding arising under section 2254."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2254?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim","1":"passim, 4, 26, 5, 26, 29, 26, 28","2":"31, 37, 43"},"q":[{"src":"brief","b":1,"text":"contrary to, or involved an unreasonable application of, clearly established Federal law, as determined by the Supreme Court of the United States.","cite":"28 U.S.C. 2254(d)(1)"},{"src":"brief","b":1,"text":"[i]n deciding whether to grant an evidentiary hearing","cite":"28 U.S.C. 2254(e)(2)"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"only on the ground that [the prisoner] is in custody in violation of the Constitution or laws or treaties of the United States.","cite":"28 U. S. C. § 2254(a)"},{"src":"argument","who":"Ms. Reaves","text":"And a transport order may be necessary or appropriate in a Section 2254 case if a prisoner shows good cause for the order and demonstrates that equitable considerations support his transport request."}]},{"t":"rule","label":"Fed. R. Civ. P. 26","url":"https://www.law.cornell.edu/rules/frcp/rule_26","by":{"0":"48","2":"47"}},{"t":"rule","label":"Fed. R. Civ. P. 35","url":"https://www.law.cornell.edu/rules/frcp/rule_35","by":{"0":"48","3":"16, 17, 19, 20"}},{"t":"case","label":"American Lithographic Co. v. Werckmeister","cite":"221 U.S. 603","y":1911,"id":"scdb/1910-165","sc":1,"by":{"1":"15","3":"15"}},{"t":"case","label":"Banister v. Davis","cite":"140 S. Ct. 1698","y":2020,"id":"2019/18-6943","sc":1,"by":{"1":"2"}},{"t":"case","label":"Barber v. Page","cite":"390 U.S. 719","y":1968,"id":"1967/703","sc":1,"by":{"1":"21"}},{"t":"case","label":"Bell v. Cone","cite":"535 U.S. 685","y":2002,"id":"2001/01-400","sc":1,"by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"modified a federal habeas court’s role in reviewing state prisoner applications in order to prevent federal habeas ‘retrials’ and to ensure that statecourt convictions are given effect to the extent possible under law.","cite":"535 U.S. 685, 693"}]},{"t":"case","label":"Christy v. Robinson","cite":"216 F. Supp. 2d 398","y":2002,"court":"D.N.J.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/216/398/","by":{"1":"14"}},{"t":"case","label":"Cottle v. Nevada Dep’t of Corrs.","cite":"2013 WL 5773845","y":2013,"court":"D. Nev. Oct. 24","by":{"1":"15"}},{"t":"case","label":"Delker v. Maass","cite":"843 F. Supp. 1390","y":1994,"court":"D. Or.","url":"https://www.courtlistener.com/c/F.%20Supp./843/1390/","by":{"1":"14"}},{"t":"case","label":"FTC v. Dean Foods","cite":"384 U.S. 597","y":1966,"id":"1965/970","sc":1,"by":{"1":"12"}},{"t":"case","label":"Gonzalez v. Thaler","cite":"565 U.S. 134","y":2012,"id":"2011/10-895","sc":1,"by":{"1":"2"}},{"t":"case","label":"Mayle v. Felix","cite":"545 U.S. 644","y":2005,"id":"2004/04-563","sc":1,"by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"Congress enacted AEDPA to advance the finality of criminal convictions,","cite":"545 U.S. 644, 662"}]},{"t":"case","label":"Preiser v. Rodriguez","cite":"411 U.S. 475","y":1973,"id":"1972/71-1369","sc":1,"by":{"1":"18"},"q":[{"src":"brief","b":1,"text":"writ of habeas corpus ad subjiciendum.","cite":"411 U.S. 475, 484 n.2"},{"src":"brief","b":1,"text":"is an attack by a person in custody upon the legality of that custody.","cite":"411 U.S. at 484"}]},{"t":"case","label":"Rasul v. Bush","cite":"542 U.S. 466","y":2004,"id":"2003/03-334","sc":1,"by":{"1":"18"}},{"t":"case","label":"Reaves v. Dep’t of Corr.","cite":"392 F. Supp. 3d 195","y":2019,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/392/195/","by":{"1":"24"},"q":[{"src":"brief","b":1,"text":"facility [with a] specialist on staff with the appropriate training to care for his medical needs.","cite":"392 F. Supp. 3d 195, 200"},{"src":"argument","who":"Chief Justice Roberts","text":"Thank you, counsel. Ms. Reaves. ORAL ARGUMENT OF NICOLE F. REAVES FOR THE UNITED STATES, AS AMICUS CURIAE, SUPPORTING NEITHER PARTY"},{"src":"argument","who":"Justice Kagan","text":"Ms. Reaves, I'm just curious, how many transports of prisoners are there daily in the prison system?"},{"src":"argument","who":"Justice Kavanaugh","text":"Reaves, on Justice Thomas's first question. So, if there's no common law analogue and no specific statutory authorization, in the end, it seems to be a policy judgment of sorts, how much we think we should analogize to other rules or what have you, as you point out."}]},{"t":"case","label":"Rees v. Peyton","cite":"384 U.S. 312","y":1966,"id":"scdb/1965-114","sc":1,"by":{"1":"7, 12, 13, 23","2":"passim","3":"10, 11"},"q":[{"src":"brief","b":2,"text":"usages and principles of the law.","cite":"384 U.S. at 313"},{"src":"argument","who":"Ms. Reaves","text":"The Court took this sort of authority for granted in Rees, and it should not now foreclose courts from issuing transport orders under the All Writs Act."},{"src":"argument","who":"Justice Sotomayor","text":"Well, once we say that there's no power ever under any circumstance, then all of the orders that we've issued in the past in Rees, ordering the transport of a prisoner to come argue before us, ordering another habeas prisoner to be examined, those were ultra vires by us, but we're stopping other courts from doing the same thing, correct?"}]},{"t":"case","label":"Schriro v. Landrigan","cite":"550 U.S. 465","y":2007,"id":"2006/05-1575","sc":1,"by":{"1":"28, 29"},"q":[{"src":"brief","b":1,"text":"a federal court must consider whether such a hearing could enable an applicant to prove the petition’s factual allegations, which, if true, would entitle the applicant to federal habeas relief.","cite":"550 U.S. at 474"},{"src":"argument","who":"Mr. O'Neil","text":"At one end is the inquiry that happens in cases like Pinholster and Schriro v. Landrigan and 2254, where the petitioner -- where the inmate is seeking to introduce known facts in evidence."}]},{"t":"case","label":"United States v. Hampton Rds. Reg’l Jail Auth.","cite":"2020 WL 5550918","y":2020,"court":"E.D.V.A. Aug. 5","by":{"1":"24"}},{"t":"case","label":"United States v. Mauro","cite":"436 U.S. 340","y":1978,"id":"1977/76-1596","sc":1,"by":{"1":"19, 21"}},{"t":"case","label":"Wilkins v. Gaddy","cite":"559 U.S. 34","y":2010,"id":"2009/08-10914","sc":1,"by":{"1":"13"}},{"t":"case","label":"Wisconsin Right to Life, Inc. v. FEC","cite":"542 U.S. 1305","y":2004,"url":"https://supreme.justia.com/cases/federal/us/542/1305/","sc":1,"by":{"1":"12"}},{"t":"case","label":"Wood v. Milyard","cite":"566 U.S. 463","y":2012,"id":"2011/10-9995","sc":1,"by":{"1":"2"}},{"t":"case","label":"Woodford v. Garceau","cite":"538 U.S. 202","y":2003,"id":"2002/01-1862","sc":1,"by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"reduce delays in the execution of state and federal criminal sentences,","cite":"538 U.S. 202, 206"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"to reduce delays in the execution of state and federal criminal sentences, particularly in capital cases,","cite":"538 U. S. 202, 206"}]},{"t":"usc","label":"42 U.S.C. § 12131","url":"https://www.law.cornell.edu/uscode/text/42/12131","by":{"1":"24"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"1":"9"}},{"t":"usc","label":"42 U.S.C. § 1997","url":"https://www.law.cornell.edu/uscode/text/42/1997","by":{"1":"10","3":"20"}},{"t":"usc","label":"18 U.S.C. § 241","url":"https://www.law.cornell.edu/uscode/text/18/241","by":{"1":"1, 13"}},{"t":"usc","label":"18 U.S.C. § 3123","url":"https://www.law.cornell.edu/uscode/text/18/3123","subs":["(b)(2)"],"by":{"1":"12"}},{"t":"usc","label":"28 U.S.C. § 2243","url":"https://www.law.cornell.edu/uscode/text/28/2243","by":{"1":"21","2":"31"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","by":{"1":"2, 21, 23, 27"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"1":"2, 7, 14, 22"}},{"t":"case","label":"Adams v. United States ex rel. McCann","cite":"317 U.S. 269","y":1942,"id":"scdb/1942-001","sc":1,"by":{"2":"passim","3":"14"},"q":[{"src":"brief","b":2,"text":"reasonably necessary in the interests of justice.","cite":"317 U.S. at 274"},{"src":"brief","b":2,"text":"is calculated in its sound judgment to achieve the ends of justice entrusted to it.","cite":"317 U.S. 269, 273"},{"src":"brief","b":3,"text":"reasonably necessary in the interest of justice.","cite":"317 U.S. at 274"}]},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"by":{"2":"20, 24","3":"2, 3"},"q":[{"src":"brief","b":2,"text":"Subjectmatter jurisdiction cannot be forfeited or waived and should be considered when fairly in doubt.","cite":"556 U.S. 662, 671"}]},{"t":"case","label":"Ayestas v. Davis","cite":"138 S. Ct. 1080","y":2018,"id":"2017/16-6795","sc":1,"by":{"2":"42, 44, 49","3":"21"},"q":[{"src":"argument","who":"Mr. O'Neil","text":"And this Court specifically addressed that stage in the -- in Ayestas. It specifically addressed it in the context of 18 U.S.C. 3599, in which Congress intended for capital -- death row inmates to have access to these investigative services."},{"src":"argument","who":"Mr. O'Neil","text":"And I think district courts, as you wrote in -- in Ayestas, district courts have plenty of experience making the kinds of determinations that the Ayestas standard contemplates."},{"src":"argument","who":"Mr. O'Neil","text":"That -- the way you just described the standard is -- is not onerous if what is required is what's required in Ayestas, which is that the claims be plausible and that there be a credible chance of overcoming procedural defeat -- procedural default."}]},{"t":"case","label":"Catlin v. United States","cite":"324 U.S. 229","y":1945,"id":"scdb/1944-071","sc":1,"by":{"2":"19"}},{"t":"case","label":"Cobbledick v. United States","cite":"309 U.S. 323","y":1940,"id":"scdb/1939-076","sc":1,"by":{"2":"19"}},{"t":"case","label":"Cohen v. Beneficial Indus. Loan Corp.","cite":"337 U.S. 541","y":1949,"id":"scdb/1948-101","sc":1,"by":{"2":"passim"},"q":[{"src":"opinion","who":"Justice Breyer, dissenting","text":"combine[s] in one review all stages of the proceeding that effectively may be reviewed and corrected if and when fnal judgment results.","cite":"337 U. S. 541, 546"},{"src":"opinion","who":"Justice Breyer, dissenting","text":"fnally determine claims of right separable from, and collateral to, rights asserted in the action.","cite":"337 U. S., at 546"},{"src":"argument","who":"Mr. O'Neil","text":"To allow the appeal to proceed now would require a dramatic expansion of the Cohen doctrine despite this Court's consistent efforts to narrow it."},{"src":"argument","who":"Mr. O'Neil","text":"So transportation orders are not appealable as a class under the blunt instrument of Cohen. Where the warden believes that there is some egregious error by a district court, it can pursue mandamus."},{"src":"argument","who":"Mr. O'Neil","text":"I mean, Justice Thomas made a -- a -- an excellent argument in Mohawk that Cohen should stay right where it is given the availability of 1292(b) and mandamus and the Rules Enabling Act, but it --"}]},{"t":"case","label":"Coopers & Lybrand v. Livesay","cite":"437 U.S. 463","y":1978,"id":"1977/76-1836","sc":1,"by":{"2":"24"},"q":[{"src":"brief","b":2,"text":"vital purpose[s] of the final-judgment rule.","cite":"437 U.S. 463, 476"}]},{"t":"case","label":"Dietz v. Bouldin","cite":"579 U.S. 40","y":2016,"id":"2015/15-458","sc":1,"by":{"2":"40"}},{"t":"case","label":"Firestone Tire & Rubber Co. v. Risjord","cite":"449 U.S. 368","y":1981,"id":"1980/79-1420","sc":1,"by":{"2":"19, 40, 43"},"q":[{"src":"brief","b":2,"text":"[T]he finality requirement embodied in § 1291 is jurisdictional in nature.","cite":"449 U.S. at 379"}]},{"t":"case","label":"Johnson v. Jones","cite":"515 U.S. 304","y":1995,"id":"1994/94-455","sc":1,"by":{"2":"24"},"q":[{"src":"brief","b":2,"text":"limited to cases presenting neat abstract issues of law.","cite":"515 U.S. at 317"},{"src":"opinion","who":"Justice Breyer, dissenting","text":"risk[ing] additional, and unnecessary, appellate court work.","cite":"515 U. S. 304, 309"},{"src":"opinion","who":"Justice Breyer, dissenting","text":"mak[e] unwise use of appellate courts' time, by forcing them to decide in the context of a less developed record, an issue very similar to one they may well decide anyway later, on a record that will permit a better decision.","cite":"515 U. S., at 317"}]},{"t":"case","label":"Link v. Wabash R. Co.","cite":"370 U.S 626","y":1962,"url":"https://www.courtlistener.com/c/U.S/370/626/","by":{"2":"41"},"q":[{"src":"brief","b":2,"text":"to manage their own affairs so as to achieve the orderly and expeditious disposition of cases","cite":"370 U.S 626, 630–31"}]},{"t":"case","label":"McFarland v. Scott","cite":"512 U.S. 849","y":1994,"id":"1993/93-6497","sc":1,"by":{"2":"10"}},{"t":"case","label":"Miller v. Hambrick","cite":"905 F.2d 259","y":1990,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/905/259/","by":{"2":"38"}},{"t":"case","label":"Mohawk Indus., Inc. v. Carpenter","cite":"558 U.S. 100","y":2009,"id":"2009/08-678","sc":1,"by":{"2":"passim","3":"1, 4, 7"},"q":[{"src":"brief","b":2,"text":"confers on federal courts of appeals jurisdiction to review ‘final decisions of the district courts.’","cite":"558 U.S. 100, 103"},{"src":"brief","b":2,"text":"effectively unreviewable on appeal from the final judgment in the underlying action.","cite":"558 U.S. at 106"},{"src":"opinion","who":"Justice Breyer, dissenting","text":"`a substantial public interest' or `some particular value of a high order.'","cite":"558 U. S., at 107"},{"src":"opinion","who":"Justice Gorsuch, dissenting","text":"the class of collaterally appealable orders . . . `narrow and selective.'","cite":"558 U. S. 100, 113"},{"src":"argument","who":"Justice Sotomayor","text":"It is conclusive under Mohawk, but we'd said there that the collateral appeal -- appealable orders are a narrow and selective class. They have to be final."},{"src":"argument","who":"Justice Sotomayor","text":"In Mohawk, many have said privilege was, so we can't go by what their practice is; we have to go by what Mohawk said, correct?"},{"src":"argument","who":"Mr. Flowers","text":"And so that brings me to the second point I wanted to reach, which is how we distinguish Mohawk, and I'm -- I'm happy for the opportunity to do so."}]},{"t":"case","label":"Ortiz v. Jordan","cite":"562 U.S. 180","y":2011,"id":"2010/09-737","sc":1,"by":{"2":"24","3":"6"}},{"t":"case","label":"Sell v. United States","cite":"539 U.S. 166","y":2003,"id":"2002/02-5664","sc":1,"by":{"2":"21","3":"3, 6"}},{"t":"case","label":"State v. Twyford","cite":"833 N.E.2d 289","y":2005,"court":"Ohio","url":"https://www.courtlistener.com/c/N.E.2d/833/289/","by":{"2":"8"}},{"t":"case","label":"Swint v. Chambers Cnty. Comm’n","cite":"514 U.S. 35","y":1995,"id":"1994/93-1636","sc":1,"by":{"2":"19, 20, 21, 25"},"q":[{"src":"brief","b":2,"text":"A ‘final decisio[n]’ is typically one ‘by which a district court disassociates itself from a case,’","cite":"514 U.S. 35, 42"}]},{"t":"case","label":"Will v. Hallock","cite":"546 U.S. 345","y":2006,"id":"2005/04-1332","sc":1,"by":{"2":"1, 19, 21","3":"3"},"q":[{"src":"brief","b":2,"text":"mentioned . . . recently without emphasizing its modest scope.","cite":"546 U.S. 345, 350"},{"src":"brief","b":2,"text":"vacate the judgment of the court of appeals and remand the case with instructions to dismiss the appeal for lack of jurisdiction.","cite":"546 U.S. 345, 355"}]},{"t":"case","label":"Zadvydas v. Davis","cite":"533 U.S. 678","y":2001,"id":"2000/99-7791","sc":1,"by":{"2":"37"}},{"t":"usc","label":"28 U.S.C. § 453","url":"https://www.law.cornell.edu/uscode/text/28/453","subs":["(1946)"],"by":{"2":"32","3":"13"}},{"t":"usc","label":"28 U.S.C. § 1292","url":"https://www.law.cornell.edu/uscode/text/28/1292","subs":["(b)"],"by":{"2":"22"}},{"t":"usc","label":"28 U.S.C. § 2072","url":"https://www.law.cornell.edu/uscode/text/28/2072","subs":["(c)"],"stext":{"head":"§2072. Rules of procedure and evidence; power to prescribe","paras":[[0,"(a) The Supreme Court shall have the power to prescribe general rules of practice and procedure and rules of evidence for cases in the United States district courts (including proceedings before magistrate judges thereof) and courts of appeals."],[0,"(b) Such rules shall not abridge, enlarge or modify any substantive right. All laws in conflict with such rules shall be of no further force or effect after such rules have taken effect."],[0,"(c) Such rules may define when a ruling of a district court is final for the purposes of appeal under section 1291 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2072?type=usc&year=mostrecent&link-type=html"},"by":{"2":"21","3":"6, 19"},"q":[{"src":"brief","b":2,"text":"defining when a ruling of a district court is final for the purposes of appeal under section 1291","cite":"28 U.S.C. § 2072(c)"}]},{"t":"case","label":"Armstrong v. Exceptional Child Center, Inc.","cite":"575 U.S. 320","y":2015,"id":"2014/14-15","sc":1,"by":{"3":"20"}},{"t":"case","label":"Brecht v. Abrahamson","cite":"507 U.S. 619","y":1993,"id":"1992/91-7358","sc":1,"by":{"3":"10"}},{"t":"case","label":"Calderon v. Thompson","cite":"521 U.S. 1136","y":1997,"url":"https://supreme.justia.com/cases/federal/us/521/1136/","sc":1,"by":{"3":"8"}},{"t":"case","label":"Carlsbad Tech., Inc. v. HIF Bio, Inc.","cite":"556 U.S. 635","y":2009,"id":"2008/07-1437","sc":1,"by":{"3":"4"}},{"t":"case","label":"Eisen v. Carlisle & Jacquelin","cite":"417 U.S. 156","y":1974,"id":"1973/73-203","sc":1,"by":{"3":"3"}},{"t":"case","label":"Foy v. United States","cite":"285 F.R.D. 407","y":2012,"court":"N.D. Iowa","url":"https://www.courtlistener.com/c/F.R.D./285/407/","by":{"3":"17"}},{"t":"case","label":"Garland v. Sullivan","cite":"737 F.2d 1283","y":1984,"court":"3rd Cir.","url":"https://www.courtlistener.com/c/F.2d/737/1283/","by":{"3":"4"}},{"t":"case","label":"Harlow v. Fitzgerald","cite":"457 U.S. 800","y":1982,"id":"1981/80-945","sc":1,"by":{"3":"2"}},{"t":"case","label":"Henderson v. United States","cite":"517 U.S. 654","y":1996,"id":"1995/95-232","sc":1,"by":{"3":"19"}},{"t":"case","label":"Kimble v. Marvel Entm’t, LLC","cite":"576 U.S. 446","y":2015,"id":"2014/13-720","sc":1,"by":{"3":"5"}},{"t":"case","label":"Lamar, Archer & Cofrin, LLP v. Appling","cite":"138 S. Ct. 1752","y":2018,"id":"2017/16-1215","sc":1,"by":{"3":"6"}},{"t":"case","label":"Mitchell v. Forsyth","cite":"472 U.S. 511","y":1985,"id":"1984/84-335","sc":1,"by":{"3":"2, 3"}},{"t":"case","label":"Moore v. Texas","cite":"139 S. Ct. 666","y":2019,"id":"2018/18-443","sc":1,"by":{"3":"22"},"q":[{"src":"argument","who":"Mr. O'Neil","text":"And what it said there, despite Texas in that case advocating for Pinholster to play the gatekeeping role, this Court did not adopt that standard, it didn't even cite Pinholster and said -- instead, it said that the standard is whether a reasonable counsel would regard the services as having likely utility."}]},{"t":"case","label":"Moses H. Cone Mem’l Hosp. v. Mercury Constr. Corp.","cite":"460 U.S. 1","y":1983,"id":"1982/81-1203","sc":1,"by":{"3":"3"}},{"t":"case","label":"Niz-Chavez v. Garland","cite":"141 S. Ct. 1474","y":2021,"id":"2020/19-863","sc":1,"by":{"3":"18"},"q":[{"src":"brief","b":3,"text":"there are (at least) two sides to the policy question[]","cite":"141 S. Ct. at 1486"}]},{"t":"case","label":"Osborn v. Haley","cite":"549 U.S. 225","y":2007,"id":"2006/05-593","sc":1,"by":{"3":"5"},"q":[{"src":"argument","who":"Mr. Flowers","text":"I understand, though Osborn, which was the last case in 2007 to recognize when the collateral order doctrine applies -- a case in which it applies, did say that the fact that the circuits were unanimous was significant."}]},{"t":"case","label":"Puerto Rico Aqueduct & Sewer Auth. v. Metcalf & Eddy, Inc.","cite":"506 U.S. 139","y":1993,"id":"1992/91-1010","sc":1,"by":{"3":"2, 3, 6"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"by":{"3":"19"}},{"t":"case","label":"Roberts v. United States Dist. Ct.","cite":"339 U.S. 844","y":1950,"id":"scdb/1949-096","sc":1,"by":{"3":"3"}},{"t":"case","label":"Schlagenhauf v. Holder","cite":"379 U.S. 104","y":1964,"id":"1964/8","sc":1,"by":{"3":"8"}},{"t":"case","label":"Stack v. Boyle","cite":"342 U.S. 1","y":1951,"id":"scdb/1951-001","sc":1,"by":{"3":"5"}},{"t":"case","label":"Stolt-Nielsen S.A. v. AnimalFeeds Int’l Corp.","cite":"559 U.S. 662","y":2010,"id":"2009/08-1198","sc":1,"by":{"3":"1"}},{"t":"case","label":"Trevino v. Thaler","cite":"569 U.S. 413","y":2013,"id":"2012/11-10189","sc":1,"by":{"3":"10"}},{"t":"case","label":"Union Pac. Ry. Co. v. Botsford","cite":"141 U.S. 250","y":1891,"id":"scdb/1890-309","sc":1,"by":{"3":"15"},"q":[{"src":"brief","b":3,"text":"no order to inspect the body of a party in a personal action appears to have been made, or even moved for, in any of the English courts of common law, at any period of their history.","cite":"141 U.S. 250, 253"}]},{"t":"case","label":"United States v. Nixon","cite":"418 U.S. 683","y":1974,"id":"1973/73-1766","sc":1,"by":{"3":"7"},"q":[{"src":"argument","who":"Mr. Flowers","text":"Nixon, that even in a -- in a situation where the President's subpoenaed to turn over documents, which is basically discovery, the -- it could be immediately appealed because of the interference with the operations of another branch."},{"src":"argument","who":"Mr. Flowers","text":"I believe you also alluded to the importance of the issue, and sovereignty is what makes that different. Again, I'd point you to United States v. Nixon, for example, which said that we're not --"},{"src":"argument","who":"Mr. Flowers","text":"It's what makes it more like the Nixon case or if you want to look at the various immunity cases where the harm of actually going to trial is fully sustained once you reach trial."}]},{"t":"case","label":"Williams v. Homeland Ins. Co.","cite":"18 F.4th 806","y":2021,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/18/806/","by":{"3":"5"}},{"t":"usc","label":"18 U.S.C. § 4244","url":"https://www.law.cornell.edu/uscode/text/18/4244","by":{"3":"10, 11"}},{"t":"usc","label":"18 U.S.C. § 4245","url":"https://www.law.cornell.edu/uscode/text/18/4245","by":{"3":"10, 11"}},{"t":"usc","label":"42 U.S.C. § 12133","url":"https://www.law.cornell.edu/uscode/text/42/12133","by":{"3":"20"}},{"t":"rule","label":"Fed. R. App. P. 3","url":"https://www.law.cornell.edu/rules/frap/rule_3","by":{"3":"6"}},{"t":"rule","label":"Fed. R. Civ. P. 34","url":"https://www.law.cornell.edu/rules/frcp/rule_34","by":{"3":"16"}},{"t":"rule","label":"Fed. R. Civ. P. 45","url":"https://www.law.cornell.edu/rules/frcp/rule_45","by":{"3":"16"}},{"t":"rule","label":"Fed. R. Civ. P. 65","url":"https://www.law.cornell.edu/rules/frcp/rule_65","by":{"3":"20"}},{"t":"rule","label":"Fed. R. Crim. P. 16","url":"https://www.law.cornell.edu/rules/frcrmp/rule_16","by":{"3":"16"}},{"t":"rule","label":"Fed. R. Crim. P. 17","url":"https://www.law.cornell.edu/rules/frcrmp/rule_17","by":{"3":"16"}}]};